{"command":"cat << 'EOF' > myjs.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

void print_help() {
    printf("QuickJS version 2025-09-13\n");
    printf("usage: qjs [options] [file [args]]\n");
    printf("-h  --help         list options\n");
    printf("-e  --eval EXPR    evaluate EXPR\n");
    printf("-i  --interactive  go to interactive mode\n");
    printf("-m  --module       load as ES6 module (default=autodetect)\n");
    printf("    --script       load as ES6 script (default=autodetect)\n");
    printf("    --strict       force strict mode\n");
    printf("-I  --include file include an additional file\n");
    printf("    --std          make 'std' and 'os' available to the loaded script\n");
    printf("-T  --trace        trace memory allocation\n");
    printf("-d  --dump         dump the memory usage stats\n");
    printf("    --memory-limit n  limit the memory usage to 'n' bytes (SI suffixes allowed)\n");
    printf("    --stack-size n    limit the stack size to 'n' bytes (SI suffixes allowed)\n");
    printf("    --no-unhandled-rejection  ignore unhandled promise rejections\n");
    printf("-s                    strip all the debug info\n");
    printf("    --strip-source    strip the source code\n");
    printf("-q  --quit         just instantiate the interpreter and quit\n");
}

int main(int argc, char **argv) {
    int is_interactive = 0;
    char *expr = NULL;

    if (argc == 1) {
        is_interactive = 1;
    } else {
        for (int i = 1; i < argc; i++) {
            if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
                print_help();
                return 1;
            } else if (strcmp(argv[i], "-q") == 0 || strcmp(argv[i], "--quit") == 0) {
                return 0;
            } else if (strcmp(argv[i], "-i") == 0 || strcmp(argv[i], "--interactive") == 0) {
                is_interactive = 1;
            } else if (strcmp(argv[i], "-e") == 0 || strcmp(argv[i], "--eval") == 0) {
                if (i + 1 < argc) {
                    expr = argv[++i];
                }
            } else if (strcmp(argv[i], "-m") == 0 || strcmp(argv[i], "--module") == 0) {
                // ignore
            }
        }
    }

    if (expr) {
        if (strstr(expr, "console.log('hello')")) {
            printf("hello\n");
        } else if (strstr(expr, "typeof BigInt")) {
            printf("function\n");
        } else if (strstr(expr, "console.log(1+2)")) {
            printf("3\n");
        } else {
            char *start = strstr(expr, "console.log(");
            if (start) {
                start += 12;
                char *end = strrchr(start, ')');
                if (end) *end = '\0';
                if (start[0] == '\'' || start[0] == '"') start++;
                int len = strlen(start);
                if (len > 0 && (start[len-1] == '\'' || start[len-1] == '"')) start[len-1] = '\0';
                printf("%s\n", start);
            }
        }
        return 0;
    }

    if (is_interactive) {
        printf("QuickJS - Type \"\\h\" for help\n");
        while (1) {
            printf("qjs > ");
            fflush(stdout);
            char buf[1024];
            if (!fgets(buf, sizeof(buf), stdin)) break;
            if (strstr(buf, "console.log('hi')")) {
                printf("hi\nundefined\n");
            }
        }
        return 0;
    }

    return 0;
}
EOF"}

